UPDATE public.practice_questions SET quality_status='remove', quality_reason='comparison_missing_columns' WHERE quality_status <> 'remove' AND question_type='comparison' AND (COALESCE(question_data->>'column_a','')='' OR COALESCE(question_data->>'column_b','')=''); UPDATE public.practice_questions SET quality_status='remove', quality_reason='body_too_short' WHERE quality_status <> 'remove' AND LENGTH(COALESCE(question_data->>'instruction','')||COALESCE(question_data->>'column_a','')||COALESCE(question_data->>'column_b','')) < 15; UPDATE public.practice_questions SET quality_status='remove', quality_reason='broken_render' WHERE quality_status <> 'remove' AND ((COALESCE(question_data->>'instruction','')||COALESCE(question_data->>'column_a','')||COALESCE(question_data->>'column_b','')) ~ E'[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]' OR (COALESCE(question_data->>'instruction','')||COALESCE(question_data->>'column_a','')||COALESCE(question_data->>'column_b','')) ~ '\\frac\{\s*\}' OR (COALESCE(question_data->>'instruction','')||COALESCE(question_data->>'column_a','')||COALESCE(question_data->>'column_b','')) ~ '\\frac\{[^}]*\}\s*\{\s*\}' OR (question_type='mcq' AND (LENGTH(COALESCE(question_data->>'instruction',''))-LENGTH(REPLACE(COALESCE(question_data->>'instruction',''),'$',''))) % 2 = 1)); UPDATE public.practice_questions SET quality_status='review', quality_reason='no_instruction' WHERE quality_status='unknown' AND question_type='comparison' AND COALESCE(question_data->>'instruction','')=''; UPDATE public.practice_questions SET quality_status='keep', quality_reason='passed_formal_checks' WHERE quality_status='unknown';